    pub fn new() -> Self {
        BayesianModel {
            nodes: HashMap::new(),
            edges: HashMap::new(),
        }
    }

    pub fn add_node(&mut self, name: &str, probability: f64) {
        self.nodes.insert(name.to_string(), probability);
    }

    pub fn add_edge(&mut self, from: &str, to: &str) {
        self.edges.entry(from.to_string()).or_insert_with(Vec::new).push(to.to_string());
    }

    pub fn infer(&self, evidence: &HashMap<String, f64>) -> HashMap<String, f64> {
        // Implement Bayesian inference algorithm
        // This is a simplified version for demonstration
        let mut result = HashMap::new();
        for (node, _) in &self.nodes {
            let mut belief = 1.0;
            for (parent, _) in &self.edges.get(node).unwrap_or(&vec![]) {
                if let Some(&prob) = evidence.get(parent) {
                    belief *= prob;
                }
            }
            result.insert(node.clone(), belief);
        }
        result
    }
}
